package com.bookrush.adminservice.api;
import java.security.Principal; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1/admin") public class AdminController { private final JdbcTemplate jdbc; public AdminController(JdbcTemplate jdbc){this.jdbc=jdbc;} private String actor(Principal p){if(p==null||p.getName()==null||p.getName().isBlank()) throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"authentication required"); return p.getName();}
 @PostMapping("/audit") public Map<String,Object> audit(@RequestBody Map<String,Object> body,Principal p){UUID id=UUID.randomUUID();String action=String.valueOf(body.getOrDefault("action","UNKNOWN"));String target=String.valueOf(body.getOrDefault("target",""));jdbc.update("insert into admin.audit_log(id,actor_subject,action,target,details) values(?,?,?,?,?::jsonb)",id,actor(p),action,target,"{}");return Map.of("id",id,"recorded",true);}
 @PostMapping("/moderation") public Object moderate(@RequestBody Map<String,Object> body,Principal p){UUID id=UUID.randomUUID();jdbc.update("insert into admin.moderation(id,target,decision,actor_subject) values(?,?,?,?)",id,String.valueOf(body.get("target")),String.valueOf(body.get("decision")),actor(p));return Map.of("id",id,"status","RECORDED");}
 @GetMapping("/moderation") public Object moderation(Principal p){actor(p);return jdbc.queryForList("select id,target,decision,actor_subject,created_at from admin.moderation order by created_at desc limit 100");}
 @GetMapping("/audit") public Object list(Principal p){actor(p);return jdbc.queryForList("select id,actor_subject,action,target,created_at from admin.audit_log order by created_at desc limit 100");}
}
